function nextFocus(ids, currentId, shift) {
  if (ids.length === 0) return null;
  const i = ids.indexOf(currentId);
  if (i === -1) return ids[0];
  const step = shift ? -1 : 1;
  return ids[(i + step + ids.length) % ids.length];
}
